import json,collections,re
for tag,p in [("v19","/tmp/opensip-design-corrections/candidate-subject.v19/docs/coop/design-corrections/foundation/identity-schemas.v2.json"),
              ("prop","/tmp/opensip-design-corrections/v20-stage-proposal.v1/work/docs/coop/design-corrections/foundation/identity-schemas.v2.json")]:
    d=json.load(open(p)); refs=[]
    arrays_missing=[]
    def walk(o,path):
        if isinstance(o,dict):
            if isinstance(o.get("$ref"),str): refs.append((path,o["$ref"], sorted(k for k in o if k!="$ref")))
            t=o.get("type")
            if t=="array" or (isinstance(t,list) and "array" in t):
                if "x-opensip-order" not in o: arrays_missing.append(path)
            for k,v in o.items(): walk(v,path+"/"+k)
        elif isinstance(o,list):
            for i,v in enumerate(o): walk(v,path+"/"+str(i))
    walk(d,"")
    shapes=collections.Counter(r for _,r,_ in refs)
    deep=[(p_,r,s) for p_,r,s in refs if len(r.split("/"))>3]
    sibs=[(p_,r,s) for p_,r,s in refs if s]
    print(f"--- {tag}: total $ref={len(refs)}, distinct={len(shapes)}, arrays-missing-order={arrays_missing}")
    print("  deep $refs:", deep)
    print("  $ref-with-siblings count:", len(sibs))
    for x in sibs[:8]: print("   ", x)
EOF

